<script lang="ts">import ChevronRight from'@fex/components-svelte/icon/chevron-right';import Trash from'@fex/components-svelte/icon/trash';import SwitchRoot from'@fex/components-svelte/primitive/switch';import SwitchThumb from'@fex/components-svelte/primitive/switch-thumb';import Transfer from'@fex/components-svelte/primitive/transfer';import Button from'@fex/components-svelte/ui/button';import Card from'@fex/components-svelte/ui/card';import{fieldNames,members}from'./data';let disabled=$state(false),targetKeys=$state<readonly(string|number)[]>(['susan','katherine'])</script>
<Card title="One-way composition" description="A custom action area only moves records to the target; target rows remove themselves through the same Transfer controller."><div class="space-y-space-md"><Transfer items={members} {fieldNames} {targetKeys} {disabled} title={{source:'Source',target:'Target'}} onChange={keys=>targetKeys=keys}>{#snippet actions(controller,snapshot)}<Button variant="outline" size="icon" aria-label="Move selected to target" disabled={!snapshot.sourceCheckedKeys.length} onclick={controller.moveToTarget}>{#snippet children()}<ChevronRight/>{/snippet}</Button>{/snippet}{#snippet targetHeader(api)}<span class="font-medium">Target</span><span class="ml-auto text-muted-foreground">{api.items.length} items</span>{/snippet}{#snippet targetBody(api)}<div class="space-y-1">{#each api.items as entry(entry.id)}<div class="flex min-h-8 items-center gap-2 px-2 text-sm"><span class="min-w-0 flex-1 truncate">{entry.name}</span><Button variant="ghost" size="icon-xs" aria-label={`Remove ${entry.name}`} disabled={disabled||entry.disabled} onclick={()=>{api.setCheckedKeys([entry.id]);api.controller.moveToSource()}}>{#snippet children()}<Trash/>{/snippet}</Button></div>{/each}</div>{/snippet}</Transfer><label class="flex w-fit items-center gap-2 text-sm text-muted-foreground"><SwitchRoot checked={disabled} onCheckedChange={value=>disabled=value}>{#snippet children()}<SwitchThumb/>{/snippet}</SwitchRoot>Disabled</label></div></Card>
